<?php

declare(strict_types=1);
namespace StageArtCore\Presentation\PublicSite;
use StageArtCore\Domain\Production\ProductionRepository;
use StageArtCore\Domain\Production\ProductionCreditRepository;
use StageArtCore\Domain\Member\MemberRepository;
final class ProductionRouter{
 public function register():void{add_action('init',[$this,'rewrite']);add_filter('query_vars',[$this,'vars']);add_action('template_redirect',[$this,'render'],2);}
 public function rewrite():void{add_rewrite_rule('^production/([^/]+)/?$','index.php?stageart_production_slug=$matches[1]','top');}
 public function vars(array$v):array{$v[]='stageart_production_slug';return$v;}
 private function released($v):bool{if(!$v)return true;try{$n=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));return$n>=new \DateTimeImmutable((string)$v,new \DateTimeZone('UTC'));}catch(\Throwable){return false;}}
 private function placeholder(string$text):void{echo'<p class="stageart-release-placeholder">'.esc_html($text).'</p>';}
 private function mapsUrl(string$value):string{return preg_match('#^https?://#i',$value)?$value:'https://www.google.com/maps/search/?api=1&query='.rawurlencode($value);}
 private function performanceCell(array$x,string$display,string$marker):string{if($display==='both'&&!empty($x['symbol']))return trim((string)$x['symbol'].' '.(string)$x['label_name']);return$display==='symbol'&&!empty($x['symbol'])?(string)$x['symbol']:$marker;}
 private function performanceTable(array$ps,array$labels,string$display,string$marker,string$legend):void{$dates=[];$times=[];$map=[];foreach($ps as$x){$d=(string)$x['performance_date'];$t=substr((string)$x['start_time'],0,5);$dates[$d]=true;$times[$t]=true;$map[$d][$t][]=$x;}$dates=array_keys($dates);$times=array_keys($times);sort($dates);sort($times);$legendHtml='';if($legend!=='none'&&$labels){$legendHtml='<div class="stageart-performance-legend">';foreach($labels as$l)$legendHtml.='<span>'.esc_html((string)$l['symbol'].' '.$l['name']).'</span>　';$legendHtml.='</div>';}if($legend==='above')echo$legendHtml;echo'<div class="stageart-performance-table-wrap"><table class="stageart-performance-table"><thead><tr><th>開演</th>';foreach($dates as$d)echo'<th>'.esc_html(wp_date('n/j',strtotime($d))).'</th>';echo'</tr></thead><tbody>';foreach($times as$t){echo'<tr><th>'.esc_html($t).'</th>';foreach($dates as$d){echo'<td>';if(!empty($map[$d][$t]))foreach($map[$d][$t]as$x){$cell=$display==='none'?$marker:$this->performanceCell($x,$display,$marker);echo'<span class="stageart-performance-cell">'.esc_html($cell).'</span>';if(!empty($x['end_time']))echo'<small>～'.esc_html(substr($x['end_time'],0,5)).'</small><br>';}echo'</td>';}echo'</tr>';}echo'</tbody></table></div>';if($legend==='below')echo$legendHtml;}
 public function render():void{$slug=get_query_var('stageart_production_slug');if(!is_string($slug)||$slug==='')return;$r=new ProductionRepository();$q=new \WP_Query(['post_type'=>'stageart_production','name'=>$slug,'post_status'=>'publish','posts_per_page'=>1]);if(!$q->have_posts()){$historical=$r->productionIdByHistoricalSlug($slug);if($historical){$old=get_post($historical);if($old&&$old->post_status==='publish'&&$old->post_name!==$slug){wp_safe_redirect(home_url('/production/'.rawurlencode($old->post_name).'/'),301);exit;}}global$wp_query;$wp_query->set_404();status_header(404);$t=get_404_template();if($t)include$t;exit;}$p=$q->posts[0];$m=get_post_meta($p->ID);$g=fn($k,$d='')=>(string)($m[$k][0]??$d);$c=new ProductionCreditRepository();get_header();echo'<main class="stageart-production"><article><h1>'.esc_html($p->post_title).'</h1>';if($this->released($g('main_image_release'))&&$g('main_image_id'))echo wp_get_attachment_image((int)$g('main_image_id'),'large');if($this->released($g('summary_release'))){if($g('summary'))echo'<p>'.esc_html($g('summary')).'</p>';}else$this->placeholder('近日公開');echo'<section><h2>公演紹介</h2>';if($this->released($g('description_release'))){if($g('description'))echo wp_kses_post($g('description'));else$this->placeholder('公演紹介はありません。');}else$this->placeholder('近日公開');echo'</section><section><h2>公演日程</h2>';if($this->released($g('schedule_release'))){if($g('schedule_start')||$g('schedule_end'))echo'<p>'.esc_html($g('schedule_start')).($g('schedule_end')?' ～ '.esc_html($g('schedule_end')):'').'</p>';else$this->placeholder('公演日程は登録されていません。');}else$this->placeholder('近日公開');echo'</section><section><h2>公演回</h2>';if(!$this->released($g('performance_release')))$this->placeholder('公演回は後日公開');else{$ps=$r->performances($p->ID);if(!$ps)$this->placeholder('現在登録されている公演回はありません。');else{$display=$g('use_labels','1')==='1'?$g('label_display','symbol'):'none';$this->performanceTable($ps,$r->labels($p->ID),$display,$g('performance_marker','●'),$g('legend','none'));}}echo'</section><section><h2>会場</h2>';if(!$this->released($g('venue_release')))$this->placeholder('近日公開');else{if($g('venue_name'))echo'<p>'.esc_html($g('venue_name')).'</p>';else$this->placeholder('会場は登録されていません。');if($g('venue_map')){if($this->released($g('venue_map_release')))echo'<p><a href="'.esc_url($this->mapsUrl($g('venue_map'))).'" target="_blank" rel="noopener">Google Mapsで見る</a></p>';else$this->placeholder('地図は後日公開');}}echo'</section>';foreach(['cast'=>'出演者','staff'=>'スタッフ']as$kind=>$title){$release=$kind==='cast'?$g('cast_release'):$g('staff_release');echo'<section><h2>'.esc_html($title).'</h2>';if(!$this->released($release))$this->placeholder('近日公開');else{$rows=$r->participants($p->ID,$kind);if(!$rows)$this->placeholder($title.'は登録されていません。');else{echo'<ul>';foreach($rows as$x){$n=esc_html($x['name']);if(!empty($x['member_id'])){$mem=(new MemberRepository())->find((int)$x['member_id']);if($mem&&$mem['status']==='published')$n='<a href="'.esc_url(home_url('/member/'.rawurlencode($mem['slug']).'/')).'">'.$n.'</a>';}echo'<li>'.$n.($x['role']?'　'.esc_html($x['role']):'').'</li>';}echo'</ul>';}}echo'</section>';}echo'<section><h2>チケット料金</h2>';if(!$this->released($g('ticket_release')))$this->placeholder('料金は後日公開');else{$ts=$r->tickets($p->ID);if(!$ts)$this->placeholder('チケット料金は登録されていません。');else{echo'<ul>';foreach($ts as$x){$tax=$g('tax_display','included')==='included'?'（税込）':($g('tax_display')==='excluded'?'（税別）':'');echo'<li>'.esc_html($x['description']).'：'.number_format($x['amount']).'円'.esc_html($tax).'</li>';}echo'</ul>';if($g('ticket_comment'))echo wp_kses_post(wpautop($g('ticket_comment')));}}echo'</section>';foreach($c->sections($p->ID,true)as$s){if(!$s['items'])continue;echo'<section><h2>'.esc_html($s['name']).'</h2><ul>';foreach($s['items']as$x)echo'<li>'.($x['url']?'<a href="'.esc_url($x['url']).'" target="_blank" rel="noopener">'.esc_html($x['name']).'</a>':esc_html($x['name'])).'</li>';echo'</ul></section>';}echo'</article></main>';get_footer();}}
